import React, { useEffect, useRef } from "react";
import "./rangeslider.css";
import './range_slider.css'
import $ from "jquery";
import _ from "lodash";

const RangeSlider = () => {

  // Update the value inside the slider handle
  const updateHandle = (e) => {
    el.textContent = e.target.val;
  }

  // Check if the slider state has changed

  return (
    <div className="main">
      <input
          type="range"
          name="participants"
          min="5"
          max="51"
          value="20"
          onChange={(e)=>{
            updateHandle(e)}
        }
      />
      <span className="rangeslider__tooltip" id ="range-tooltip" ref={$tooltip}></span>
    </div>
  );
};

export default RangeSlider;
